files.content:
'use client';

import { useId, useMemo, useState, type HTMLAttributes, type JSX, type ReactNode, type Ref } from 'react';
import {
  DropZone,
  FieldErrorContext,
  FileTrigger,
  ProgressBar,
  isFileDropItem,
  useLocale,
  type DropZoneProps,
  type ValidationResult,
} from 'react-aria-components';
import { IconAlertCircle, IconCircleCheck, IconFile, IconUpload, IconX } from '@tabler/icons-react';
import { Button } from './button';
import { Description, FieldError, Label } from './text-field';
import styles from './file-upload.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

/** A selected file plus optional upload state, for showing progress or a per-file error. */
export interface FileUploadEntry {
  file: File;
  /** Upload progress 0–100. Shows a bar while below 100 and "Uploaded" at 100. */
  progress?: number;
  /** Per-file error, e.g. "Upload failed. Try again." */
  error?: string;
}

export interface FileUploadProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange' | 'children' | 'defaultValue'> {
  ref?: Ref<HTMLDivElement>;
  /** Visible label, e.g. "Attachments". */
  label?: ReactNode;
  /** Help text under the label. */
  description?: ReactNode;
  /** Field-level error, shown under the list when `isInvalid` is true. */
  errorMessage?: ReactNode;
  isInvalid?: boolean;
  isDisabled?: boolean;
  /** MIME types or extensions, e.g. `['image/*', '.pdf']`. Files that don't match are rejected with a message. */
  acceptedFileTypes?: string[];
  /** Allow more than one file. Without it, a new file replaces the current one. */
  allowsMultiple?: boolean;
  /** Maximum size per file in bytes. Larger files are rejected with a message. */
  maxSize?: number;
  /** Controlled list. Pass `File`s, or `FileUploadEntry`s to show progress or errors. */
  files?: ReadonlyArray<File | FileUploadEntry>;
  /** Initial list when uncontrolled. */
  defaultFiles?: File[];
  /** Called with the full list of accepted files whenever it changes (add or remove). */
  onChange?: (files: File[]) => void;
  /** Called with files that were rejected (wrong type, too large, over the limit). */
  onReject?: (rejections: FileRejection[]) => void;
  /** Text under the prompt. Defaults to the accepted types and max size, e.g. "PNG, PDF, up to 10 MB". */
  hint?: ReactNode;
  /** Prompt text before the browse link. */
  dropLabel?: ReactNode;
  /** Text of the browse link. */
  browseLabel?: ReactNode;
}

export interface FileRejection {
  file: File;
  reason: 'type' | 'size' | 'count';
  message: string;
}

const isEntry = (f: File | FileUploadEntry): f is FileUploadEntry => 'file' in f && typeof f.file === 'object';
const sameFile = (a: File, b: File) => a.name === b.name && a.size === b.size && a.lastModified === b.lastModified;

function matchesAccept(file: File, accepted: readonly string[]): boolean {
  if (accepted.length === 0) return true;
  const name = file.name.toLowerCase();
  const type = file.type.toLowerCase();
  return accepted.some((raw) => {
    const a = raw.trim().toLowerCase();
    if (a.startsWith('.')) return name.endsWith(a);
    if (a.endsWith('/*')) return type.startsWith(a.slice(0, -1));
    return type === a;
  });
}

const SUBTYPE_NAMES: Record<string, string> = {
  jpeg: 'JPG',
  'svg+xml': 'SVG',
  plain: 'TXT',
  msword: 'DOC',
  'vnd.openxmlformats-officedocument.wordprocessingml.document': 'DOCX',
  'vnd.ms-excel': 'XLS',
  'vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'XLSX',
  'vnd.openxmlformats-officedocument.presentationml.presentation': 'PPTX',
};
const WILDCARD_NAMES: Record<string, string> = { image: 'Images', video: 'Videos', audio: 'Audio', text: 'Text files' };

function typeName(raw: string): string {
  const a = raw.trim().toLowerCase();
  if (a.startsWith('.')) return a.slice(1).toUpperCase();
  const [major = '', sub = ''] = a.split('/');
  if (sub === '*') return WILDCARD_NAMES[major] ?? 'Files';
  return SUBTYPE_NAMES[sub] ?? sub.toUpperCase();
}

/** Bytes → "2.4 MB" (1024-based, locale-formatted). */
function formatFileSize(bytes: number, locale = 'en-US'): string {
  const units = ['byte', 'kilobyte', 'megabyte', 'gigabyte'] as const;
  let value = bytes;
  let i = 0;
  while (value >= 1024 && i < units.length - 1) {
    value /= 1024;
    i++;
  }
  return new Intl.NumberFormat(locale, {
    style: 'unit',
    unit: units[i],
    unitDisplay: i === 0 ? 'long' : 'short',
    maximumFractionDigits: i > 0 && value < 10 ? 1 : 0,
  }).format(value);
}

const INVALID: ValidationResult = {
  isInvalid: true,
  validationErrors: [],
  validationDetails: {
    badInput: false,
    customError: true,
    patternMismatch: false,
    rangeOverflow: false,
    rangeUnderflow: false,
    stepMismatch: false,
    tooLong: false,
    tooShort: false,
    typeMismatch: false,
    valid: false,
    valueMissing: false,
  },
};

/**
 * A drop zone with a browse button, and the list of chosen files underneath. Files can also be pasted
 * while the drop zone has focus. Validates type and size on the way in; progress and per-file errors
 * come from you through `files`.
 */
export function FileUpload({
  label,
  description,
  errorMessage,
  isInvalid = false,
  isDisabled = false,
  acceptedFileTypes,
  allowsMultiple = false,
  maxSize,
  files,
  defaultFiles,
  onChange,
  onReject,
  hint,
  dropLabel = 'Drag files here or',
  browseLabel = 'browse',
  className,
  ...rest
}: FileUploadProps): JSX.Element {
  const { locale } = useLocale();
  const id = useId();
  const labelId = `${id}-label`;
  const descriptionId = `${id}-description`;
  const hintId = `${id}-hint`;
  const errorId = `${id}-error`;
  const [internal, setInternal] = useState<File[]>(defaultFiles ?? []);
  const [rejected, setRejected] = useState<FileRejection[]>([]);

  const entries: FileUploadEntry[] = useMemo(
    () => (files ?? internal).map((f) => (isEntry(f) ? f : { file: f })),
    [files, internal],
  );
  const accepted = acceptedFileTypes ?? [];

  let autoHint = '';
  if (hint === undefined) {
    const parts: string[] = [];
    if (accepted.length) {
      const names = [...new Set(accepted.map(typeName))];
      parts.push(new Intl.ListFormat(locale, { type: 'unit', style: 'short' }).format(names));
    }
    if (maxSize != null) parts.push(`up to ${formatFileSize(maxSize, locale)}`);
    const text = parts.join(', ');
    autoHint = text ? text.charAt(0).toUpperCase() + text.slice(1) : '';
  }
  const hintContent = hint ?? autoHint;

  const commit = (next: File[]) => {
    if (files === undefined) setInternal(next);
    onChange?.(next);
  };

  const addFiles = (incoming: File[]) => {
    if (isDisabled || incoming.length === 0) return;
    const current = entries.map((e) => e.file);
    const ok: File[] = [];
    const bad: FileRejection[] = [];
    for (const file of incoming) {
      if (!matchesAccept(file, accepted)) {
        bad.push({ file, reason: 'type', message: `This file type isn't accepted.` });
      } else if (maxSize != null && file.size > maxSize) {
        bad.push({ file, reason: 'size', message: `Larger than ${formatFileSize(maxSize, locale)}.` });
      } else if (!allowsMultiple && ok.length > 0) {
        bad.push({ file, reason: 'count', message: 'Only one file can be added.' });
      } else if (!current.some((c) => sameFile(c, file)) && !ok.some((c) => sameFile(c, file))) {
        ok.push(file);
      }
    }
    setRejected(bad);
    if (bad.length) onReject?.(bad);
    if (ok.length) commit(allowsMultiple ? [...current, ...ok] : ok.slice(0, 1));
  };

  const onDrop: DropZoneProps['onDrop'] = async (e) => {
    const dropped = await Promise.all(e.items.filter(isFileDropItem).map((item) => item.getFile()));
    addFiles(dropped);
  };

  const remove = (file: File) => commit(entries.map((e) => e.file).filter((f) => f !== file));

  const showError = isInvalid && errorMessage != null;
  const describedBy =
    [hintContent && hintId, description != null && descriptionId, showError && errorId].filter(Boolean).join(' ') || undefined;

  return (
    <div
      {...rest}
      className={cx(styles.field, className)}
      data-disabled={isDisabled || undefined}
      data-invalid={isInvalid || undefined}
    >
      {label != null && (
        <Label id={labelId} elementType="span">
          {label}
        </Label>
      )}
      <DropZone
        className={styles.zone}
        isDisabled={isDisabled}
        onDrop={onDrop}
        aria-labelledby={label != null ? labelId : undefined}
      >
        <span className={styles.zoneIcon} aria-hidden>
          <IconUpload />
        </span>
        <span className={styles.prompt}>
          {dropLabel}{' '}
          <FileTrigger
            acceptedFileTypes={acceptedFileTypes}
            allowsMultiple={allowsMultiple}
            onSelect={(list) => addFiles(list ? Array.from(list) : [])}
          >
            <Button variant="link" isDisabled={isDisabled} aria-describedby={describedBy} className={styles.browse}>
              {browseLabel}
            </Button>
          </FileTrigger>
        </span>
        {hintContent ? (
          <span id={hintId} className={styles.hint}>
            {hintContent}
          </span>
        ) : null}
      </DropZone>
      {description != null && <Description id={descriptionId}>{description}</Description>}
      {showError && (
        <FieldErrorContext.Provider value={INVALID}>
          <FieldError id={errorId}>{errorMessage}</FieldError>
        </FieldErrorContext.Provider>
      )}

      {entries.length + rejected.length > 0 && (
        <ul className={styles.list} aria-labelledby={label != null ? labelId : undefined}>
          {entries.map(({ file, progress, error }, i) => (
            <FileRow
              key={`${file.name}-${file.size}-${file.lastModified}-${i}`}
              file={file}
              progress={progress}
              error={error}
              locale={locale}
              isDisabled={isDisabled}
              onRemove={() => remove(file)}
            />
          ))}
          {rejected.map((r, i) => (
            <FileRow
              key={`rejected-${r.file.name}-${i}`}
              file={r.file}
              error={r.message}
              locale={locale}
              isDisabled={isDisabled}
              isRejected
              onRemove={() => setRejected((all) => all.filter((x) => x !== r))}
            />
          ))}
        </ul>
      )}
    </div>
  );
}

function FileRow({
  file,
  progress,
  error,
  locale,
  isDisabled,
  isRejected = false,
  onRemove,
}: {
  file: File;
  progress?: number;
  error?: string;
  locale: string;
  isDisabled: boolean;
  isRejected?: boolean;
  onRemove: () => void;
}): JSX.Element {
  const uploading = progress != null && progress < 100 && !error;
  const done = progress != null && progress >= 100 && !error;
  return (
    <li className={styles.row} data-error={error ? true : undefined}>
      <span className={styles.fileIcon} aria-hidden>
        {error ? <IconAlertCircle /> : <IconFile />}
      </span>
      <div className={styles.fileBody}>
        <div className={styles.fileLine}>
          <span className={styles.fileName} title={file.name}>
            {file.name}
          </span>
          <span className={styles.fileSize}>{formatFileSize(file.size, locale)}</span>
        </div>
        {uploading && (
          <ProgressBar value={progress} aria-label={`Uploading ${file.name}`} className={styles.progress}>
            {({ percentage, valueText }) => (
              <>
                <span className={styles.track}>
                  <span className={styles.fill} style={{ inlineSize: `${percentage ?? 0}%` }} />
                </span>
                <span className={styles.percent}>{valueText}</span>
              </>
            )}
          </ProgressBar>
        )}
        {done && (
          <span className={styles.status}>
            <IconCircleCheck aria-hidden />
            Uploaded
          </span>
        )}
        {error && (
          <span className={styles.error} role={isRejected ? 'alert' : undefined}>
            {error}
          </span>
        )}
      </div>
      <Button
        variant="ghost"
        size="icon"
        aria-label={isRejected ? `Dismiss ${file.name}` : `Remove ${file.name}`}
        isDisabled={isDisabled}
        onPress={onRemove}
        className={styles.remove}
      >
        <IconX />
      </Button>
    </li>
  );
}

/* FileUpload: dashed drop zone + list of chosen files. */
.field {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: var(--strata-space-2);
  inline-size: 100%;
  min-inline-size: 0;
}

.zone {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--strata-space-2);
  inline-size: 100%;
  padding-block: var(--strata-space-6);
  padding-inline: var(--strata-space-4);
  border: 1px dashed var(--strata-color-border-strong);
  border-radius: var(--strata-radius-container);
  background: var(--strata-color-surface-default);
  color: var(--strata-color-text-default);
  text-align: center;
  outline: none;
}
.zone[data-focus-visible] {
  outline: 2px solid var(--strata-color-focus-ring);
  outline-offset: 2px;
}
.zone[data-drop-target] {
  border-style: solid;
  border-color: var(--strata-color-action-primary-bg);
  background: var(--strata-color-surface-selected);
}
.field[data-invalid] .zone {
  border-color: var(--strata-color-feedback-danger-solid);
}
.zone[data-disabled] {
  border-color: var(--strata-color-border-default);
  background: var(--strata-color-surface-sunken);
  color: var(--strata-color-text-disabled);
}

.zoneIcon {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--strata-control-height);
  block-size: var(--strata-control-height);
  margin-block-end: var(--strata-space-1);
  border: 1px solid var(--strata-color-border-default);
  border-radius: var(--strata-radius-pill);
  background: var(--strata-color-surface-raised);
  color: var(--strata-color-text-subtle);
  box-shadow: var(--strata-shadow-raised);
}
.zoneIcon > svg {
  inline-size: 1.25em;
  block-size: 1.25em;
  stroke-width: 1.75;
}
.zone[data-drop-target] .zoneIcon {
  border-color: var(--strata-color-action-primary-bg);
  color: var(--strata-color-text-brand);
}
.zone[data-disabled] .zoneIcon {
  color: var(--strata-color-text-disabled);
  box-shadow: none;
}

.prompt {
  font-size: var(--strata-font-size-md);
  font-weight: var(--strata-font-weight-medium);
  line-height: var(--strata-line-height-snug);
}
.prompt .browse {
  vertical-align: baseline;
}

.hint {
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-sm);
  line-height: var(--strata-line-height-snug);
}
.zone[data-disabled] .hint {
  color: var(--strata-color-text-disabled);
}

.list {
  display: flex;
  flex-direction: column;
  gap: var(--strata-space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}

.row {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--strata-space-3);
  min-inline-size: 0;
  padding-block: var(--strata-space-2);
  padding-inline: var(--strata-space-3) var(--strata-space-2);
  border: 1px solid var(--strata-color-border-default);
  border-radius: min(var(--strata-radius-container), var(--strata-space-3));
  background: var(--strata-color-surface-default);
}
.row[data-error] {
  border-color: var(--strata-color-feedback-danger-border);
}

.fileIcon {
  box-sizing: border-box;
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  inline-size: calc(var(--strata-control-height) - var(--strata-space-1));
  block-size: calc(var(--strata-control-height) - var(--strata-space-1));
  border-radius: min(var(--strata-radius-field), var(--strata-space-2));
  background: var(--strata-color-surface-sunken);
  color: var(--strata-color-text-subtle);
}
.fileIcon > svg {
  inline-size: 1.15em;
  block-size: 1.15em;
  stroke-width: 1.75;
}
.row[data-error] .fileIcon {
  background: var(--strata-color-feedback-danger-bg);
  color: var(--strata-color-feedback-danger-fg);
}

.fileBody {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: var(--strata-space-1);
  min-inline-size: 0;
}
.fileLine {
  display: flex;
  align-items: baseline;
  gap: var(--strata-space-2);
  min-inline-size: 0;
}
.fileName {
  flex: 0 1 auto;
  min-inline-size: 0;
  overflow: hidden;
  color: var(--strata-color-text-default);
  font-size: var(--strata-font-size-md);
  font-weight: var(--strata-font-weight-medium);
  line-height: var(--strata-line-height-snug);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.fileSize {
  flex: none;
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-sm);
  font-variant-numeric: tabular-nums;
  line-height: var(--strata-line-height-snug);
}

.progress {
  display: flex;
  align-items: center;
  gap: var(--strata-space-2);
}
.track {
  position: relative;
  flex: 1;
  block-size: var(--strata-space-1);
  overflow: hidden;
  border-radius: var(--strata-radius-pill);
  background: color-mix(in oklab, var(--strata-color-text-default) 10%, transparent);
}
.fill {
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  border-radius: inherit;
  background: var(--strata-color-action-primary-bg);
}
.percent {
  flex: none;
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-xs);
  font-variant-numeric: tabular-nums;
  line-height: var(--strata-line-height-snug);
}

.status {
  display: inline-flex;
  align-items: center;
  gap: var(--strata-space-1);
  color: var(--strata-color-feedback-success-fg);
  font-size: var(--strata-font-size-sm);
  line-height: var(--strata-line-height-snug);
}
.status > svg {
  inline-size: 1.1em;
  block-size: 1.1em;
}

.error {
  color: var(--strata-color-feedback-danger-fg);
  font-size: var(--strata-font-size-sm);
  line-height: var(--strata-line-height-snug);
}

.remove {
  flex: none;
}

@media (prefers-reduced-motion: no-preference) {
  .zone {
    transition:
      background-color var(--strata-motion-duration-fast) var(--strata-motion-easing),
      border-color var(--strata-motion-duration-fast) var(--strata-motion-easing);
  }
  .fill {
    transition: inline-size var(--strata-motion-duration-normal) var(--strata-motion-easing);
  }
}
